window.StrictDoc.search.nodesByMid = {"1":{"MID":"b03f3864b2aa4ef09d0d6136e458e47e","UID":"HLR-001","TITLE":"ANTLR Grammar Parsing","STATEMENT":"The system shall parse training data using ANTLR-based grammars.","RATIONALE":"ANTLR provides robust grammar-based parsing with support for complex language structures.","PRIORITY":"High","_LINK":"HLR-001"},"2":{"MID":"b7ccd5d077f645438273e75d9fbf07ce","UID":"HLR-002","TITLE":"Multiple Input Formats","STATEMENT":"The system shall support parsing multiple input data formats (JSON, CSV, text).","RATIONALE":"Flexibility in input formats enables integration with various data sources.","PRIORITY":"High","_LINK":"HLR-002"},"3":{"MID":"1a82e4d84bd9499dba744c87f69df736","UID":"HLR-003","TITLE":"Data Validation","STATEMENT":"The system shall validate parsed data against defined schemas.","RATIONALE":"Schema validation ensures data integrity and consistency.","PRIORITY":"High","_LINK":"HLR-003"},"4":{"MID":"ba7111610282467996b54dc43bc2a0e9","UID":"HLR-004","TITLE":"Error Handling","STATEMENT":"The system shall provide detailed error messages for malformed input.","RATIONALE":"Clear error reporting improves user experience and debugging.","PRIORITY":"Medium","_LINK":"HLR-004"},"5":{"MID":"2f269d43cd8044b28be393a11b5a9178","UID":"HLR-005","TITLE":"Type Safety","STATEMENT":"The system shall enforce strict type checking throughout the codebase.","RATIONALE":"Static type checking prevents runtime errors and improves code maintainability.","PRIORITY":"Medium","_LINK":"HLR-005"},"6":{"MID":"5c3dbdbced654e90bd99418139ad9657","UID":"HLR-006","TITLE":"Documentation Generation","STATEMENT":"The system shall support generation of structured documentation from parsed data.","RATIONALE":"Auto-generated documentation ensures consistency and reduces manual effort.","PRIORITY":"Medium","_LINK":"HLR-006"},"7":{"MID":"a1b4df457cb44ab5a8a1687e9a8af00e","UID":"HLR-007","TITLE":"Configurable Synonym Loading","STATEMENT":"The system shall allow users to configure exercise name synonyms via external configuration files, enabling customization of name mappings without modifying source code.","RATIONALE":"External configuration decouples synonym data from application logic, allowing non-developers to maintain and extend name mappings independently.","PRIORITY":"High","_LINK":"HLR-007"},"8":{"MID":"d066832bd3de443b9c587be246be9558","UID":"HLR-008","TITLE":"Multiple Synonym Configuration Formats","STATEMENT":"The system shall support YAML and JSON file formats for synonym configuration files.","RATIONALE":"Supporting industry-standard formats (YAML for readability, JSON for programmatic generation) gives users flexibility in tooling and workflow integration.","PRIORITY":"Medium","_LINK":"HLR-008"},"9":{"MID":"8e1d8ba58bcc445ca2d0b43eb3a54b36","UID":"HLR-009","TITLE":"Synonym Configuration Validation","STATEMENT":"The system shall validate synonym configuration files at load time and report descriptive errors for any structural or semantic violations.","RATIONALE":"Fail-fast validation at initialization prevents silent misconfiguration and provides actionable feedback to users when configurations are malformed.","PRIORITY":"High","_LINK":"HLR-009"},"10":{"MID":"be37f6bd8716403aabc6e44b003b4829","UID":"HLR-010","TITLE":"Backward-Compatible Default Synonyms","STATEMENT":"The system shall provide built-in default synonym mappings and operate fully without any user-supplied configuration file.","RATIONALE":"Backward compatibility ensures existing integrations and users are unaffected by the introduction of external configuration support.","PRIORITY":"High","_LINK":"HLR-010"},"11":{"MID":"2e3937c5f59548478a8522dcfb8ca20d","UID":"HLR-011","TITLE":"Synonym-Based Internationalization","STATEMENT":"The system shall support internationalization of exercise names by allowing language-specific synonym configuration files to be provided independently per use case.","RATIONALE":"Internationalization through configurable synonyms enables adoption across different linguistic communities without requiring code-level changes.","PRIORITY":"Medium","_LINK":"HLR-011"},"12":{"MID":"d0cda3d07891414db4f013bed6c97310","UID":"HLR-012","TITLE":"Use the Training Parser via a Language Server Protocol (LSP)","STATEMENT":"The system shall support the use of the Training Parser via a Language Server Protocol (LSP) to provide language-specific features and enhancements. User shall be able to use the Training Parser in any IDE that supports LSP","RATIONALE":"Do not force users to use a specific IDE for Training Parser. Do not force users to use a program for the Training Parser.","PRIORITY":"Medium","_LINK":"HLR-012"},"13":{"MID":"2ed6488e96884ca4824ab2738e271dd7","UID":"HLR-13","TITLE":"Tracking statistics in the Input File","STATEMENT":"Track the statistics for a workout session\n","RATIONALE":"A single place for the user to input their statistics, rather than manually when processing the file.\n\nWhen: doing, not when reviewing\n","_LINK":"HLR-13"},"14":{"MID":"8ce759fdbcff49d7bc57cf22fedc3874","UID":"LLR-SYN-1","TITLE":"Optional config_path Constructor Parameter","STATEMENT":"The StandardizeName class shall accept an optional config_path parameter of type Path | str | None in its constructor. When the parameter is None (default), built-in default synonyms shall be used.","RATIONALE":"A single optional parameter preserves the existing call signature and enables opt-in configuration without forcing changes on existing callers.","PRIORITY":"High","_LINK":"LLR-SYN-1"},"15":{"MID":"c7d60617b9044d93b8d4c83db98b8240","UID":"LLR-SYN-2","TITLE":"YAML Synonym File Loading","STATEMENT":"The system shall load synonym configurations from files with .yaml or .yml extensions by parsing them as YAML documents using a standards-compliant YAML parser.","PRIORITY":"Medium","_LINK":"LLR-SYN-2"},"16":{"MID":"fe704e1dd6e04703a1bc376ce32274cf","UID":"LLR-SYN-3","TITLE":"JSON Synonym File Loading","STATEMENT":"The system shall load synonym configurations from files with .json extension by parsing them as JSON documents using a standards-compliant JSON parser.","PRIORITY":"Medium","_LINK":"LLR-SYN-3"},"17":{"MID":"3e9b71d4c1874e4bad77af647eed5967","UID":"LLR-SYN-4","TITLE":"Unsupported Format Error","STATEMENT":"The system shall raise a ValueError with a descriptive message when the config_path refers to a file whose extension is neither .yaml, .yml, nor .json.","RATIONALE":"An explicit error on unsupported formats prevents silent failures and guides users toward supported alternatives.","PRIORITY":"Medium","_LINK":"LLR-SYN-4"},"18":{"MID":"681b72dfa23f4555a84cca6c42d16513","UID":"LLR-SYN-5","TITLE":"Root Key Validation","STATEMENT":"The system shall validate that the parsed configuration document contains a top-level synonyms key whose value is a list. A missing key or non-list value shall raise a ValueError with a descriptive message.","PRIORITY":"High","_LINK":"LLR-SYN-5"},"19":{"MID":"a868f7bdef404f0d8c34b0332c511ba5","UID":"LLR-SYN-6","TITLE":"Synonym Entry Structure Validation","STATEMENT":"The system shall validate that each entry in the synonyms list contains exactly a clean key (string) and a synonyms key (list of strings). Missing or incorrectly typed fields shall raise a ValueError.","PRIORITY":"High","_LINK":"LLR-SYN-6"},"20":{"MID":"e1d8d3802013494dbe08b6faa31a5006","UID":"LLR-SYN-7","TITLE":"Overlapping Synonym Detection","STATEMENT":"The system shall detect and reject configurations in which the same synonym string appears in more than one entry. Such overlap shall raise an AssertionError or ValueError identifying the conflicting synonym.","RATIONALE":"Overlapping synonyms produce non-deterministic normalization results; rejecting them at load time enforces correctness.","PRIORITY":"High","_LINK":"LLR-SYN-7"},"21":{"MID":"baa0423a5c3d413b8a950a7d59382985","UID":"LLR-SYN-8","TITLE":"Duplicate Clean Name Detection","STATEMENT":"The system shall detect and reject configurations in which the same clean name appears in more than one entry. Such duplication shall raise a ValueError identifying the duplicate clean name.","PRIORITY":"High","_LINK":"LLR-SYN-8"},"22":{"MID":"63036d4bb84b4891923a630b0820790e","UID":"LLR-SYN-9","TITLE":"Missing File Error","STATEMENT":"The system shall raise a FileNotFoundError with a descriptive message when the specified config_path does not refer to an existing file.","PRIORITY":"Medium","_LINK":"LLR-SYN-9"},"23":{"MID":"a1d9a9d64ce64d4daf02a182cbe96be1","UID":"LLR-SYN-11","TITLE":"Case-Insensitive Synonym Matching","STATEMENT":"The system shall match exercise name inputs to synonyms in a case-insensitive manner, converting the input to a canonical form before lookup.","RATIONALE":"Users enter exercise names in varying capitalization; case-insensitive matching reduces friction and avoids missed normalization.","PRIORITY":"Medium","_LINK":"LLR-SYN-11"},"24":{"MID":"763a15127ce24b37a5f3e549fb8caca1","UID":"LLR-SYN-12","TITLE":"Path Object and String Path Acceptance","STATEMENT":"The config_path parameter shall accept both pathlib.Path objects and plain string paths interchangeably, converting strings to Path internally as needed.","RATIONALE":"Supporting both types matches Python idioms and avoids forcing callers to convert their path representations.","PRIORITY":"Low","_LINK":"LLR-SYN-12"},"25":{"MID":"6331f457fac84f78ab337871810cb8c6","UID":"LLR-SYN-13","TITLE":"Per-Instance Independent Configuration","STATEMENT":"Each StandardizeName instance shall maintain its own synonym mapping independently, so that multiple instances with different config_path values may coexist in the same process without interference.","RATIONALE":"Independent instances are required to enable simultaneous parsing with different synonym sets (e.g., per-language parsers).","PRIORITY":"Medium","_LINK":"LLR-SYN-13"},"26":{"MID":"7196371908c4451d90dece229e3deffd","UID":"LLR-SYN-14","TITLE":"Eager Load at Initialization","STATEMENT":"The system shall load and validate the synonym configuration during __init__ (eagerly), not deferred to the first use of the run() method.","RATIONALE":"Eager loading ensures that configuration errors surface immediately at construction time rather than mid-parse, simplifying error handling for callers.","PRIORITY":"Medium","_LINK":"LLR-SYN-14"},"27":{"MID":"1404e3bf581f4353ac24060f2d0603d1","UID":"LLR-PARSER-001","TITLE":"Reporting of incorrect input in the training data","STATEMENT":"Any incorrect input in the training data should be reported.","RATIONALE":"The user should be alerted when the input is incorrect, to able to correct the input. It is at the input time that the user should be alerted, not at later stages.","PRIORITY":"High","_LINK":"LLR-PARSER-001"},"28":{"MID":"4b85b056a2f84c8fa5d0484ba4d70ddc","UID":"LLR-PARSER-2","TITLE":"Exercises can have 1..* letters in its name","STATEMENT":"As long as the exercise contains one letter, it is a valid exercise name.\n","RATIONALE":"Some synonyms, or exercise names, can be only one letter in length\n","_LINK":"LLR-PARSER-2"},"29":{"MID":"bb94d9cbf58148ae8e86b54d51ebc165","UID":"LLR-LSP-1","TITLE":"Reporting of incorrect input in the training data","STATEMENT":"TODO","RATIONALE":"TODO","PRIORITY":"High","_LINK":"LLR-LSP-1"},"30":{"MID":"289f45662e054b26a4bae548a91008b3","UID":"LLR-LSP-2","TITLE":"Commenting of lines via LSP","STATEMENT":"TODO\n","RATIONALE":"TODO\n","PRIORITY":"High\n","_LINK":"LLR-LSP-2"},"31":{"MID":"316eb59b5b3c460d9783bae6ea41b2a0","UID":"LLR-LSP-3","TITLE":"Computing the subtotal of volume, series","STATEMENT":"TODO\n","RATIONALE":"TODO\n","PRIORITY":"High\n","_LINK":"LLR-LSP-3"}};
